import fs from 'node:fs'
import http from 'node:http'
import path from 'node:path'
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import type { AddressInfo } from 'node:net'
import { configureRuntime } from '../runtime-env'
import { KEV_4B_ID, desktopCatalog } from '../models-manager'

// The one fake in the Kev runtime tests: the runtime store, as a local HTTP server serving a
// small runtime archive. Everything the app does with it is the real code.

/** A response the store sends instead of the archive: an outage, or a server that mishandles Range. */
export interface KevRuntimeStoreResponse {
  status: number
  headers?: Record<string, string>
  body?: Buffer
}

export interface KevRuntimeStore {
  readonly data: string
  readonly archive: Buffer
  readonly sha256: string
  /** The python3 path the started Kev runtime wrote, once it ran. */
  readonly recordFile: string
  /** Range headers of every archive request, in order. */
  readonly requests: { range?: string }[]
  /** Serve these bytes instead of the archive (a corrupted download). */
  serve(bytes: Buffer): void
  /** Answer every archive request with this response until `reset`. */
  respondWith(response: KevRuntimeStoreResponse): void
  writeManifest(sha256?: string, bytes?: number): void
  /** Fresh profile with Kev 4B's model files on disk and no runtime: an install after updating. */
  reset(): Promise<void>
  close(): Promise<void>
}

/**
 * The runtime store publishes Kev's runtime for Apple silicon Macs only. A Linux or Intel CI
 * runner reports that host for the test, so the same download, verify and install journey runs
 * there: the HTTP server, tar, the filesystem and the started process all stay real.
 * Returns the function that restores the real host.
 */
export function reportAppleSiliconHost(): () => void {
  const platform = Object.getOwnPropertyDescriptor(process, 'platform')!
  const arch = Object.getOwnPropertyDescriptor(process, 'arch')!
  Object.defineProperty(process, 'platform', { ...platform, value: 'darwin' })
  Object.defineProperty(process, 'arch', { ...arch, value: 'arm64' })
  return () => {
    Object.defineProperty(process, 'platform', platform)
    Object.defineProperty(process, 'arch', arch)
  }
}

function sparseFile(filePath: string, size: number): void {
  fs.mkdirSync(path.dirname(filePath), { recursive: true })
  const descriptor = fs.openSync(filePath, 'w')
  fs.ftruncateSync(descriptor, size)
  fs.closeSync(descriptor)
}

async function installKevModelFiles(models: string): Promise<void> {
  const kev = (await desktopCatalog()).find((model) => model.id === KEV_4B_ID)!
  const shards = kev.files
    .map((file) => path.basename(file.name))
    .filter((name) => /^model\.safetensors-\d+-of-\d+\.safetensors$/.test(name))
  for (const file of kev.files) {
    const target = path.join(models, file.name)
    if (path.basename(file.name) !== 'model.safetensors.index.json') {
      sparseFile(target, file.sizeBytes ?? 0)
      continue
    }
    const index = JSON.stringify({
      weight_map: Object.fromEntries(shards.map((shard, i) => [`layer.${i}.weight`, shard]))
    })
    fs.mkdirSync(path.dirname(target), { recursive: true })
    fs.writeFileSync(target, index.padEnd(file.sizeBytes ?? index.length, ' '))
  }
}

/** A runtime whose python3 behaves like the Kev server: it records which Python started,
 *  reports its device, and serves /v1/models on the port it was given. */
function runtimeArchive(root: string): Buffer {
  const source = path.join(root, 'archive-source')
  const python = path.join(source, 'kev-runtime', 'python', 'bin', 'python3')
  fs.mkdirSync(path.dirname(python), { recursive: true })
  fs.writeFileSync(
    python,
    `#!${process.execPath}
const fs = require('node:fs')
const http = require('node:http')
fs.writeFileSync(process.env.KEV_TEST_RECORD, process.argv[1])
const port = Number(process.argv[process.argv.indexOf('--port') + 1])
http.createServer((request, response) => {
  response.writeHead(request.url === '/v1/models' ? 200 : 404, { 'content-type': 'application/json' })
  response.end('{"data":[]}')
}).listen(port, '127.0.0.1', () => console.error('[Kev] loaded: device=mps'))
`,
    { mode: 0o755 }
  )
  const output = path.join(root, 'kev-runtime.tar.gz')
  execFileSync('tar', ['-czf', output, '-C', source, 'kev-runtime'])
  return fs.readFileSync(output)
}

export async function startKevRuntimeStore(root: string): Promise<KevRuntimeStore> {
  const data = path.join(root, 'data')
  const resources = path.join(root, 'resources')
  const bin = path.join(root, 'bin')
  const recordFile = path.join(root, 'started-python.txt')
  const archive = runtimeArchive(root)
  const sha256 = createHash('sha256').update(archive).digest('hex')
  const requests: { range?: string }[] = []
  let served = archive
  let override: KevRuntimeStoreResponse | null = null
  const server = http.createServer((request, response) => {
    const range = request.headers.range
    requests.push({ range })
    if (override) {
      response.writeHead(override.status, override.headers)
      response.end(override.body ?? '')
      return
    }
    const start = range ? Number(/bytes=(\d+)-/.exec(range)?.[1] ?? 0) : 0
    const body = served.subarray(start)
    response.writeHead(range ? 206 : 200, {
      'content-length': String(body.length),
      ...(range ? { 'content-range': `bytes ${start}-${served.length - 1}/${served.length}` } : {})
    })
    response.end(body)
  })
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))
  const baseUrl = `http://127.0.0.1:${(server.address() as AddressInfo).port}`

  const writeManifest = (pin = sha256, bytes = archive.length): void => {
    fs.mkdirSync(resources, { recursive: true })
    fs.writeFileSync(
      path.join(resources, 'kev-runtime-packs.json'),
      JSON.stringify({
        schemaVersion: 1,
        'darwin-arm64': {
          url: `${baseUrl}/desktop/kev-runtime/darwin-arm64/test-v1.tar.gz`,
          sha256: pin,
          bytes,
          version: 'test-v1'
        }
      })
    )
  }

  return {
    data,
    archive,
    sha256,
    recordFile,
    requests,
    serve: (bytes) => {
      served = bytes
    },
    respondWith: (next) => {
      override = next
    },
    writeManifest,
    reset: async () => {
      fs.rmSync(data, { recursive: true, force: true })
      fs.rmSync(recordFile, { force: true })
      requests.length = 0
      served = archive
      override = null
      configureRuntime({ dataDir: data, binRoots: [bin], resourceDirs: [resources] })
      sparseFile(path.join(bin, 'kev-local-server.py'), 1)
      writeManifest()
      await installKevModelFiles(path.join(data, 'models'))
      process.env.KEV_TEST_RECORD = recordFile
    },
    close: async () => {
      delete process.env.KEV_TEST_RECORD
      configureRuntime({ dataDir: undefined, binRoots: undefined, resourceDirs: undefined })
      await new Promise<void>((resolve) => server.close(() => resolve()))
      fs.rmSync(root, { recursive: true, force: true })
    }
  }
}

import { describe, expect, it } from 'vitest'
import { authorizeBearer, authorizeBearerAny } from '../mcp-auth-logic'

const TOKEN = 'a'.repeat(64)

describe('authorizeBearer', () => {
  it('accepts the exact Bearer token (case-insensitive scheme)', () => {
    expect(authorizeBearer(`Bearer ${TOKEN}`, TOKEN)).toBe(true)
    expect(authorizeBearer(`bearer ${TOKEN}`, TOKEN)).toBe(true)
    expect(authorizeBearer(`  Bearer   ${TOKEN}  `, TOKEN)).toBe(true)
  })

  it('rejects a wrong, missing, or malformed token (fail closed)', () => {
    expect(authorizeBearer(`Bearer ${'b'.repeat(64)}`, TOKEN)).toBe(false) // wrong value
    expect(authorizeBearer(`Bearer ${TOKEN}x`, TOKEN)).toBe(false) // wrong length
    expect(authorizeBearer(undefined, TOKEN)).toBe(false) // no header
    expect(authorizeBearer(TOKEN, TOKEN)).toBe(false) // missing "Bearer " scheme
    expect(authorizeBearer(`Basic ${TOKEN}`, TOKEN)).toBe(false) // wrong scheme
  })

  it('never authorizes against a blank / too-short configured token', () => {
    expect(authorizeBearer('Bearer ', '')).toBe(false)
    expect(authorizeBearer('Bearer short', 'short')).toBe(false)
  })
})

describe('authorizeBearerAny (per-device: match ANY live token)', () => {
  const A = 'a'.repeat(64)
  const B = 'b'.repeat(64)

  it('authorizes a bearer that matches any token in the live set', () => {
    expect(authorizeBearerAny(`Bearer ${A}`, [A, B])).toBe(true)
    expect(authorizeBearerAny(`Bearer ${B}`, [A, B])).toBe(true)
  })

  it('rejects a bearer that matches NONE of the live tokens', () => {
    expect(authorizeBearerAny(`Bearer ${'c'.repeat(64)}`, [A, B])).toBe(false)
  })

  it('fails closed on an empty set - THIS is the un-paired case', () => {
    // When a device is un-paired its token leaves the live set; with nothing left it can never
    // authorize. An empty set is exactly what a Mac with no tools-allowed peers reports.
    expect(authorizeBearerAny(`Bearer ${A}`, [])).toBe(false)
  })

  it('still rejects a missing / malformed bearer even with tokens present', () => {
    expect(authorizeBearerAny(undefined, [A, B])).toBe(false)
    expect(authorizeBearerAny(A, [A, B])).toBe(false) // no "Bearer " scheme
  })
})

import { describe, expect, it, vi } from 'vitest'
import { beginOAuthAuthorization, cancelOAuthAuthorization } from '../mcp-oauth-cancellation'

describe('connector OAuth cancellation registry', () => {
  it('cancels only the named connector and clears the registration', () => {
    const first = vi.fn()
    const second = vi.fn()
    beginOAuthAuthorization(101, first)
    beginOAuthAuthorization(202, second)

    expect(cancelOAuthAuthorization(101)).toBe(true)
    expect(first).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Authorization cancelled' })
    )
    expect(second).not.toHaveBeenCalled()
    expect(cancelOAuthAuthorization(101)).toBe(false)

    cancelOAuthAuthorization(202)
  })

  it('cancels an older attempt when a connector starts a new one', () => {
    const older = vi.fn()
    const newer = vi.fn()
    beginOAuthAuthorization(303, older)
    const finishNewer = beginOAuthAuthorization(303, newer)

    expect(older).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Authorization superseded by a newer request' })
    )
    finishNewer()
    expect(cancelOAuthAuthorization(303)).toBe(false)
    expect(newer).not.toHaveBeenCalled()
  })

  it('does not let an older completion clear a newer attempt', () => {
    const older = vi.fn()
    const newer = vi.fn()
    const finishOlder = beginOAuthAuthorization(404, older)
    beginOAuthAuthorization(404, newer)

    finishOlder()
    expect(cancelOAuthAuthorization(404)).toBe(true)
    expect(newer).toHaveBeenCalledWith(
      expect.objectContaining({ message: 'Authorization cancelled' })
    )
  })
})

import { describe, expect, it } from 'vitest'
import { z } from 'zod'
import { jsonSchemaToZodShape } from '../mcp-tool-schema'

describe('jsonSchemaToZodShape', () => {
  it('maps types, marks non-required keys optional, and keeps descriptions', () => {
    const shape = jsonSchemaToZodShape({
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Event title' },
        allDay: { type: 'boolean' },
        count: { type: 'integer' },
        tags: { type: 'array', items: { type: 'string' } }
      },
      required: ['title']
    })
    const obj = z.object(shape)
    expect(obj.safeParse({ title: 'x' }).success).toBe(true) // only the required field
    expect(obj.safeParse({ title: 'x', allDay: true, count: 2, tags: ['a'] }).success).toBe(true)
    expect(obj.safeParse({}).success).toBe(false) // missing required title
    expect(obj.safeParse({ title: 'x', count: 'nope' }).success).toBe(false) // wrong type
    // The description carries through to the Zod schema (MCP surfaces it).
    expect((shape.title as z.ZodString).description).toBe('Event title')
  })

  it('handles an empty schema and enum properties', () => {
    expect(jsonSchemaToZodShape({ type: 'object', properties: {} })).toEqual({})
    const shape = jsonSchemaToZodShape({
      properties: { key: { type: 'string', enum: ['Enter', 'Tab'] } },
      required: ['key']
    })
    const obj = z.object(shape)
    expect(obj.safeParse({ key: 'Enter' }).success).toBe(true)
    expect(obj.safeParse({ key: 'Nope' }).success).toBe(false)
  })
})

